module watchdog_timer(  
    input wire clk,  
    input wire rst,  
    input wire wd_signal,  
    output reg reset_out  
);  
    parameter TIMEOUT = 10;  // Timeout period in clock cycles  
    reg [3:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            reset_out <= 0;  
        end else if (wd_signal) begin  
            counter <= 0;  
            reset_out <= 0;  
        end else if (counter < TIMEOUT) begin  
            counter <= counter + 1;  
            reset_out <= 0;  
        end else begin  
            reset_out <= 1;  
        end  
    end  
endmodule

