    // Initialize weights
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= 16'h0000; // Initialize weights to zero
            end
        end else begin
            // Shift input buffer
            for (i = N-1; i > 0; i = i - 1) begin
                x_buffer[i] <= x_buffer[i-1];
            end
            x_buffer[0] <= x; // New input

            // Compute output
            y <= 0;
            for (i = 0; i < N; i = i + 1) begin
                y <= y + (w[i] * x_buffer[i]);
            end

            // Update weights
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= w[i] + (mu * (d - y) * x_buffer[i]);
            end
        end
    end
endmodule

