module carrier_recovery(input clk, input reset, input modulated_signal, output reg carrier_signal);  
    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            carrier_signal <= 0;  
        end else begin  
            counter <= counter + 1;  
            if (counter == 4'd15) begin  
                carrier_signal <= modulated_signal;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

