module flash_memory_cell (  
    input wire D,  
    input wire WE,  
    input wire RE,  
    output reg Q  
);  
    always @(posedge WE or posedge RE) begin  
        if (WE)  
            Q <= D;  
    end  
    always @(posedge RE) begin  
        if (RE)  
            Q <= Q; // This line maintains the previous state if RE is high  
    end  
endmodule

