module neural_network (  
    input clk,  
    input rst,  
    input [7:0] x1,  
    input [7:0] x2,  
    input [7:0] target,  
    output reg [7:0] output_val  
);  
    reg [7:0] w1 [0:1];  // Weights for input layer  
    reg [7:0] w2 [0:1];  // Weights for hidden layer  
    reg [7:0] hidden [0:1];  
    reg [7:0] output_temp;  
    reg [7:0] error;  
    integer i;  

    initial begin  
        w1[0] = 8'd1;  
        w1[1] = 8'd1;  
        w2[0] = 8'd1;  
        w2[1] = 8'd1;  
    end  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            output_val <= 0;  
        end else begin  
            // Forward Pass  
            hidden[0] <= (x1 * w1[0]) + (x2 * w1[1]);  
            hidden[1] <= (x1 * w1[0]) + (x2 * w1[1]);  
            output_temp <= (hidden[0] * w2[0]) + (hidden[1] * w2[1]);  

            // Activation Function (Step Function)  
            if (output_temp > 8'd128)  
                output_val <= 8'd255;  
            else  
                output_val <= 8'd0;  

            // Backpropagation (Weight Update)  
            error <= target - output_val;  
            for (i = 0; i < 2; i = i + 1) begin  
                w2[i] <= w2[i] + (8'd1 * error * hidden[i]);  
                w1[i] <= w1[i] + (8'd1 * error * x1);  
            end  
        end  
    end  
endmodule

