module rsa_encryption #(parameter BIT_WIDTH = 8) (  
    input clk,  
    input reset,  
    input [BIT_WIDTH-1:0] plaintext,  
    input [BIT_WIDTH-1:0] key,  
    output reg [BIT_WIDTH-1:0] ciphertext  
);  
    reg [BIT_WIDTH-1:0] modulus;  
    reg [BIT_WIDTH-1:0] encrypted_value;  
    reg [BIT_WIDTH-1:0] exponent;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            modulus <= 8'b10000000; // example modulus, can be set as needed  
            encrypted_value <= 0;  
            ciphertext <= 0;  
            exponent <= key;  
        end else begin  
            encrypted_value <= (plaintext ** exponent) % modulus;  
            ciphertext <= encrypted_value;  
        end  
    end  
endmodule

