module CSPRNG (  
    input clk,  
    input reset,  
    input [4:0] seed,  
    output reg [4:0] random_out  
);  
    reg [4:0] lfsr;  
    wire feedback;  

    // Feedback polynomial: x^5 + x^3 + 1  
    assign feedback = lfsr[4] ^ lfsr[2];  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            lfsr <= seed;  
        end else begin  
            lfsr <= {lfsr[3:0], feedback};  
        end  
    end  

    always @(posedge clk) begin  
        random_out <= lfsr;  
    end  
endmodule

