module PLL (
    input clk_in,
    input reset,
    output reg clk_out
);

reg [1:0] clk_div;

always @(posedge clk_in or posedge reset) begin
    if (reset) begin
        clk_div <= 2'b00;
        clk_out <= 0;
    end else begin
        clk_div <= clk_div + 1;
        if (clk_div == 2'b01) begin
            clk_out <= ~clk_out;
        end
    end
end

endmodule

