module pipeline_cpu (
    input clk,
    input reset,
    input [3:0] instruction_in,
    output reg [3:0] result_out
);
    reg [3:0] IF_ID_instr;
    reg [3:0] ID_EX_instr;
    reg [3:0] EX_MEM_instr;
    reg [3:0] MEM_WB_instr;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            IF_ID_instr <= 4'b0000;
            ID_EX_instr <= 4'b0000;
            EX_MEM_instr <= 4'b0000;
            MEM_WB_instr <= 4'b0000;
            result_out <= 4'b0000;
        end else begin
            // Instruction Fetch
            IF_ID_instr <= instruction_in;
            // Instruction Decode
            ID_EX_instr <= IF_ID_instr;
            // Execute
            EX_MEM_instr <= ID_EX_instr;
            // Memory Access and Write Back
            if (EX_MEM_instr == 4'b0001) // ADD
                result_out <= result_out + 1;
            else if (EX_MEM_instr == 4'b0010) // SUB
                result_out <= result_out - 1;
            else if (EX_MEM_instr == 4'b0011) // MUL
                result_out <= result_out * 2;
            MEM_WB_instr <= EX_MEM_instr;
        end
    end
endmodule

