module i2c_master(  
    input wire clk,  
    input wire rst,  
    input wire start,  
    input wire [6:0] address,  
    input wire [7:0] data_in,  
    output reg scl,  
    output reg sda  
);  

    reg [3:0] state;  
    parameter IDLE = 4'b0000, START = 4'b0001, ADDRESS = 4'b0010, WRITE = 4'b0011, STOP = 4'b0100;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            scl <= 1;  
            sda <= 1;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        sda <= 0;  
                        state <= START;  
                    end  
                end  
                START: begin  
                    scl <= 0;  
                    state <= ADDRESS;  
                end  
                ADDRESS: begin  
                    // Send address (MSB first)  
                    // This is a simplified implementation, typically requires a shift register  
                    sda <= address[6];  
                    state <= WRITE;  
                end  
                WRITE: begin  
                    // Send data (MSB first)  
                    sda <= data_in[7];  
                    state <= STOP;  
                end  
                STOP: begin  
                    scl <= 1;  
                    sda <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

