module LIFO_Stack (  
    input wire clk,  
    input wire rst,  
    input wire push,  
    input wire pop,  
    input wire [3:0] data_in,  
    output reg [3:0] data_out,  
    output reg overflow,  
    output reg underflow  
);  

    reg [3:0] stack [0:7];  
    reg [2:0] sp; // stack pointer  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            sp <= 3'b000;  
            overflow <= 0;  
            underflow <= 0;  
        end else begin  
            if (push) begin  
                if (sp < 3'b111) begin  
                    stack[sp] <= data_in;  
                    sp <= sp + 1;  
                    overflow <= 0;  
                end else begin  
                    overflow <= 1;  
                end  
            end  
            if (pop) begin  
                if (sp > 3'b000) begin  
                    sp <= sp - 1;  
                    data_out <= stack[sp - 1];  
                    underflow <= 0;  
                end else begin  
                    underflow <= 1;  
                end  
            end  
        end  
    end  
endmodule

