module uart_tx #(parameter BAUD_RATE_DIV = 104) (  
    input wire clk,  
    input wire rst,  
    input wire tx_en,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg tx_busy  
);  
    reg [3:0] bit_count;  
    reg [10:0] baud_rate_counter;  
    reg [9:0] tx_shift_reg;  
    reg sending;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            baud_rate_counter <= 0;  
            tx_busy <= 0;  
            sending <= 0;  
            tx <= 1;  
            bit_count <= 0;  
        end else begin  
            if (sending) begin  
                baud_rate_counter <= baud_rate_counter + 1;  
                if (baud_rate_counter == BAUD_RATE_DIV) begin  
                    baud_rate_counter <= 0;  
                    if (bit_count < 10) begin  
                        tx <= tx_shift_reg[0];  
                        tx_shift_reg <= {1'b1, tx_shift_reg[9:1]};  
                        bit_count <= bit_count + 1;  
                    end else begin  
                        sending <= 0;  
                        tx_busy <= 0;  
                        tx <= 1;  
                        bit_count <= 0;  
                    end  
                end  
            end else if (tx_en) begin  
                tx_shift_reg <= {1'b1, data_in, 1'b0};  
                sending <= 1;  
                tx_busy <= 1;  
            end  
        end  
    end  
endmodule

