module i2c_controller(  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    input wire [7:0] data_in,  
    output reg [7:0] data_out,  
    output reg ack,  
    output reg sda,  
    output reg scl  
);  
    reg [3:0] state;  
    parameter IDLE = 4'b0000,  
              START = 4'b0001,  
              SEND_ADDR = 4'b0010,  
              SEND_DATA = 4'b0011,  
              READ_DATA = 4'b0100,  
              STOP = 4'b0101;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            sda <= 1;  
            scl <= 1;  
            ack <= 0;  
            data_out <= 8'b0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (enable)  
                        state <= START;  
                end  
                START: begin  
                    sda <= 0;  
                    state <= SEND_ADDR;  
                end  
                SEND_ADDR: begin  
                    // Assuming a 7-bit address + R/W bit  
                    // Logic to send address (omitted for brevity)  
                    state <= SEND_DATA;  
                end  
                SEND_DATA: begin  
                    sda <= data_in;  
                    state <= READ_DATA;  
                end  
                READ_DATA: begin  
                    // Logic to read data (omitted for brevity)  
                    data_out <= 8'b10101010; // Dummy read data  
                    ack <= 1;  
                    state <= STOP;  
                end  
                STOP: begin  
                    sda <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

